16	// Caret is the chip's own solid disclosure triangle; Down/Up/Right are the
17	// lighter strokes the menu rows use.
18	// PanelOpen and PanelClosed are the right pane's two states; PanelLeftOpen
19	// and PanelLeftClosed mirror the same glyph for the left pane.
20	enum class HeaderIcon { None, Back, Down, Up, Right, Caret, More, Printer, Monitor, Check, Eye, Lock, Slice, Slicing, Plates, Export, Print, Cancel,
21	                        PanelOpen, PanelClosed, PanelLeftOpen, PanelLeftClosed };
