24	// into a graphics context for shell surfaces that paint their own rows.
25	void draw_header_icon(wxGraphicsContext& gc, HeaderIcon icon, double x, double y, double size, const wxColour& color);
26	
27	// ChipLeft and ChipRight are the two halves of the printer/filament chip. Each is
28	// a separate focus target, and each paints its own outer half of one shared
29	// outline, the way PrimaryLeft/PrimaryRight already split the print action.
30	enum class HeaderStyle { Quiet, ChipLeft, ChipRight, PrimaryLeft, PrimaryRight, Outline, Menu };
31	
32	// The surface a button sits on, which a Quiet or Outline button takes as its
33	// own fill at rest. Canvas is the project header's; Raised is a dialog's.
34	enum class HeaderSurface { Canvas, Raised };
35	
36	// A status is a colour plus a word, never a colour alone: the design system
37	// requires state to be readable without relying on hue.
38	enum class StatusTone { None, Neutral, Positive, Busy, Warning };
39	
40	// One dot in a row of filament slots. A faded dot keeps its colour at low
41	// strength: a slot the current plate does not print with.
42	struct SlotDot
43	{
44	    wxColour colour;
45	    bool     faded{false};
46	};
47	
48	// Everything a menu row can carry beyond its label. Grouped rather than spread
49	// over a dozen setters because HeaderMenu builds a row in one shot, and a row
50	// with no decoration should read as exactly that at the call site.
51	struct HeaderRowDecoration
52	{
53	    // Text ahead of everything else on the row, in the label's own face -- a
54	    // slot's number, which the design reads before the slot's dot.
55	    wxString lead;
56	    // Leading dot. Set with a valid colour for a filled swatch; set with an
57	    // invalid colour for the dashed outline of a colour nobody chose.
58	    std::optional<wxColour> dot;
59	    // A row of slot dots before the label, in slot order, then a grey "+n"
60	    // when slots were folded away. Small dots let many slots fit.
61	    std::vector<SlotDot> slot_dots;
62	    wxString             slot_more;
63	    bool                 small_slot_dots{false};
64	    // Right-aligned secondary text, in the label role.
65	    wxString   detail;
66	    // Draws the detail immediately after the label, separated by a middot,
67	    // instead of right-aligning it. The chip's nozzle reads as part of one
68	    // line -- "X1 Carbon · 0.4" -- while staying regular beside the bold
69	    // printer name, which one text run could not do.
70	    bool       detail_inline{false};
71	    // Second line under the label, in text/secondary.
72	    wxString   sub_label;
73	    bool       bold{false};
74	    bool       danger{false};
75	    bool       check{false};
76	    HeaderIcon trailing{HeaderIcon::None};
77	    StatusTone status{StatusTone::None};
78	    wxString   status_word;
79	};
80	
81	// Fork-owned painting, with the same wxEVT_BUTTON contract as native controls.
82	// Each half of the split action remains a separate keyboard focus target.
83	class HeaderButton : public wxControl
84	{
85	public:
86	    HeaderButton(wxWindow* parent, const ShellTheme& theme, HeaderStyle style,
87	                 const wxString& label, HeaderIcon icon);
88	    void set_dark(bool dark);
89	    void set_surface(HeaderSurface surface) { m_surface = surface; Refresh(); }
90	    void set_icon(HeaderIcon icon);
91	    void set_status(bool visible, bool warning = false);
92	    void set_detail(const wxString& detail);
93	    void set_decoration(HeaderRowDecoration decoration);
94	    // A second, interactive glyph at the row's right end, revealed while the
95	    // row is hovered or selected. Clicking it -- or right-clicking the row --
96	    // raises wxEVT_MENU instead of wxEVT_BUTTON, so one row can carry a
97	    // secondary action without a second focusable control.
98	    void set_row_action(HeaderIcon icon);
99	    void set_row_action_label(const wxString& label);
100	    const wxString& row_action_label() const { return m_row_action_label; }
101	    bool has_row_action() const { return m_row_action != HeaderIcon::None || !m_row_action_label.empty(); }
102	    // Raises the row action as though its glyph had been clicked.
103	    void invoke_row_action();
104	    const HeaderRowDecoration& decoration() const { return m_decoration; }
105	    // Caps the label before it ellipsizes, so one long preset name cannot push
106	    // the rest of the header off the row. 0 means no cap.
107	    void set_label_cap(int cap_dip);
108	    void set_menu_selected(bool selected) { m_menu_selected = selected; Refresh(); }
109	    // A primary-left half squares its right edge only while a menu half sits beside it.
110	    void set_attached(bool attached) { m_attached = attached; Refresh(); }
111	    // A menu trigger holds a pressed fill and flips its chevron for as long as
112	    // its menu is open. HeaderMenu owns the flag; nothing else may set it.
113	    void set_open(bool open) { m_open = open; Refresh(); }
114	    bool is_open() const { return m_open; }
115	    // Whether the last activation came from Return/Space rather than a click.
116	    // A menu anchored here highlights its first row only in the keyboard case.
117	    bool activated_by_keyboard() const { return m_keyboard_activated; }
118	    void SetLabel(const wxString& label) override;
119	    bool Enable(bool enabled = true) override;
120	    wxSize DoGetBestSize() const override;
121	    // As with Orca's custom Button, macOS must ask the wx control rather
122	    // than the generic NSView whether it can become first responder.
123	    bool AcceptsFocus() const override { return true; }
124	    // Draws the control into an offscreen bitmap using the same code the paint
125	    // event uses, so appearance can be verified from inside the running
126	    // application in both modes without a screen capture.
127	    wxBitmap snapshot();
128	
129	private:
130	    void paint(wxPaintEvent&);
131	    void draw(wxDC& dc, wxGraphicsContext& context, const wxSize& client);
132	    void activate(bool from_keyboard);
133	    const wxFont& role_font() const;
134	    const wxFont& detail_font() const;
135	    int  trailing_reserve() const;
136	    // Width of the slot-dot run and its "+n", gap to the label included; zero
137	    // without slot dots. Shared by measuring and painting.
138	    int  slot_dots_width() const;
139	    // Width of the leading text and its gap; zero without one.
140	    int  lead_width() const;
141	    // Screen rect of the row-action glyph, empty when there is none.
142	    wxRect row_action_rect() const;
143	    const ShellTheme& m_theme;
144	    HeaderStyle m_style;
145	    HeaderSurface m_surface{HeaderSurface::Canvas};
146	    HeaderIcon m_icon;
147	    HeaderRowDecoration m_decoration;
148	    HeaderIcon m_row_action{HeaderIcon::None};
149	    wxString m_row_action_label;
150	    int m_label_cap{0};
151	    bool m_dark{false}, m_hover{false}, m_pressed{false}, m_status{false}, m_warning{false};
152	    bool m_menu_selected{false};
153	    bool m_attached{true};
154	    bool m_open{false};
155	    bool m_keyboard_activated{false};
156	};
157	
158	struct HeaderMenuItem {
159	    wxString label;
160	    HeaderIcon icon{HeaderIcon::None};
161	    wxString detail;
162	    bool enabled{true};
163	    bool separator{false};
164	    std::function<void()> invoke;
165	    // A title row: an Eyebrow-styled caption that is never selectable and
166	    // never invokable. `label` carries the caption.
167	    bool title{false};
168	    // Keeps the popup open when invoked -- for a row that swaps the menu's own
169	    // contents (a sub-list, a back step) rather than finishing a task.
170	    bool keeps_open{false};
171	    // Secondary action at the row's right end. Icon actions appear on hover
172	    // and keep the popup open for a nested step; text actions can dismiss it.
173	    HeaderIcon row_action{HeaderIcon::None};
174	    std::function<void()> invoke_row_action;
175	    HeaderRowDecoration decoration;
176	    // The row's window name, which lookups and assistive technology read;
177	    // empty uses the label. Set when the row draws part of what it says
178	    // outside the label, as a slot row draws its number. Last, so rows
179	    // written positionally elsewhere stay as they are.
180	    wxString name;
181	    // A visible compact text button at the row's right edge. The row itself
182	    // can remain non-invokable; keyboard activation invokes the text action.
183	    wxString row_action_label;
184	    bool dismisses_on_row_action{false};
185	};
