187	// A custom view among a menu's rows that takes part in the menu's keyboard
188	// model -- the filament menu's colour row. The menu moves into it with Up
189	// from the row below it (or Down from the row above), and out of it again the
190	// same way; while it is in, Left, Right, Return and Space are the view's.
191	class HeaderMenuKeyView
192	{
193	public:
194	    virtual ~HeaderMenuKeyView() = default;
195	    // Shows or hides the view's own focus mark.
196	    virtual void set_key_focus(bool focused) = 0;
197	    // Left, Right, Return or Space while the view has the keyboard. Returns
198	    // false for a key it does not use.
199	    virtual bool on_menu_key(int key_code) = 0;
200	    // The child the keyboard is on, for tests and assistive technology.
201	    virtual wxWindow* key_child() const = 0;
202	};
