204	// Right-aligned transient menu. The popup owns only presentation; callbacks
205	// return to the owner after dismissal, never run commands inside mouse capture.
206	//
207	// A menu can also replace its own contents in place -- the filament menu's
208	// slot views do this rather than opening a second popup, so the popup keeps
209	// its position, its keyboard model, and its dismissal handling.
210	class HeaderMenu : public PopupWindow
211	{
212	public:
213	    HeaderMenu(wxWindow* parent, const ShellTheme& theme, bool dark,
214	               std::vector<HeaderMenuItem> items);
215	    // Which edge of the anchor the popup lines up with: Right opens under a
216	    // control at the window's right (the header), Left under one at its left
217	    // (the Plates pane), so a menu never opens toward the window's edge.
218	    enum class Align { Right, Left };
219	    void open(HeaderButton& anchor, Align align = Align::Right);
220	    HeaderButton* selected_item() const { return m_selected < 0 ? nullptr : m_items[m_selected]; }
221	    // The custom view, when it takes part in the keyboard model, and whether
222	    // the keyboard is in it now.
223	    HeaderMenuKeyView* key_view() const;
224	    bool               key_view_active() const { return m_header_active && key_view() != nullptr; }
225	
226	    // Swaps the rows for a new set and re-lays out at the same anchor. The
227	    // width stays put so the popup does not jump as the person types.
228	    void replace_items(std::vector<HeaderMenuItem> items);
229	    // A custom view among the rows -- the filament menu's colour row. The
230	    // builder runs with the popup as parent; nullptr clears it.
231	    // `after_rows` places the custom view below that many rows, so a step can
232	    // keep its title/back row at the top where the design puts it.
233	    void set_header_builder(std::function<wxWindow*(wxWindow*)> builder, int after_rows = 0);
234	    // Invoked when the popup dismisses for any reason, after the anchor has
235	    // been released. Used to drop menu-owned state the owner is holding.
236	    void set_dismiss_listener(std::function<void()> listener) { m_dismissed = std::move(listener); }
237	
238	    // Dismisses the popup and releases its anchor. Public because closing a
239	    // menu is a normal thing for an owner (or a test) to ask for; Dismiss()
240	    // alone would leave the anchor painting its open state.
241	    void close();
242	
243	protected:
244	    void OnDismiss() override;
245	
246	private:
247	    void select_item(int index);
248	    void enter_key_view();
249	    void leave_key_view();
250	    void build(std::vector<HeaderMenuItem> items);
251	    void on_key(wxKeyEvent& event);
252	    void reposition();
253	
254	    const ShellTheme& m_theme;
255	    bool m_dark{false};
256	    std::vector<HeaderButton*> m_items;
257	    wxWindow* m_header{nullptr};
258	    std::function<wxWindow*(wxWindow*)> m_header_builder;
259	    int m_header_after_rows{0};
260	    // The first selectable row below the custom view, and whether the
261	    // keyboard is in the view. The flag survives a rebuild, so a view that
262	    // rebuilds the menu on Return keeps the keyboard.
263	    int  m_header_item_index{-1};
264	    bool m_header_active{false};
265	    std::function<void()> m_dismissed;
266	    wxWeakRef<HeaderButton> m_anchor;
267	    Align m_align{Align::Right};
268	    bool m_closed{false};
269	    int m_selected{-1};
270	    int m_width{0};
271	};
