986	    };
987	    // A .3mf opens as a project through OrcaSlicer's load_project, which asks
988	    // the "Previously opened file" question; files beside it are added to it.
989	    if (std::any_of(files.begin(), files.end(), [&](const auto& file) { return has_extension(file, ".3mf"); }))
